def countMoreOnes(bits):
    cnt = {0: 1}
    s = 0
    less = 0
    total = 0
    for b in bits:
        if b:
            less += cnt.get(s, 0)
            s += 1
        else:
            s -= 1
            less -= cnt.get(s, 0)
        total += less
        cnt[s] = cnt.get(s, 0) + 1
    return total
